// Generated by cmake/EmbedFile.cmake from src/rt/device_programs.cu.
extern const unsigned char g_devicePrograms[];
extern const std::size_t g_deviceProgramsSize;

namespace ooc {
namespace {

void logCallback(unsigned int level, const char* tag, const char* message, void*) {
  std::fprintf(stderr, "[optix][%u][%s] %s\n", level, tag, message);
}

constexpr unsigned kGeometryFlags = OPTIX_GEOMETRY_FLAG_DISABLE_ANYHIT | OPTIX_GEOMETRY_FLAG_REQUIRE_SINGLE_ANYHIT_CALL;

OptixAccelBuildOptions buildOptions() {
  OptixAccelBuildOptions o{};
  o.buildFlags = OPTIX_BUILD_FLAG_PREFER_FAST_TRACE | OPTIX_BUILD_FLAG_ALLOW_COMPACTION;
  o.operation = OPTIX_BUILD_OPERATION_BUILD;
  return o;
}

OptixBuildInput customInput(const CUdeviceptr* aabbs, uint32_t n, const unsigned* flags) {
  OptixBuildInput in{};
  in.type = OPTIX_BUILD_INPUT_TYPE_CUSTOM_PRIMITIVES;
  in.customPrimitiveArray.aabbBuffers = aabbs;
  in.customPrimitiveArray.numPrimitives = n;
  in.customPrimitiveArray.strideInBytes = 0;
  in.customPrimitiveArray.flags = flags;
  in.customPrimitiveArray.numSbtRecords = 1;
  return in;
}

}  // namespace

OptixEngine::OptixEngine(bool validation) {
  CUDA_CHECK(cudaFree(nullptr));  // create the primary context
  OPTIX_CHECK(optixInit());
  OptixDeviceContextOptions opts{};
  opts.logCallbackFunction = &logCallback;
  opts.logCallbackLevel = 3;
  opts.validationMode = validation ? OPTIX_DEVICE_CONTEXT_VALIDATION_MODE_ALL : OPTIX_DEVICE_CONTEXT_VALIDATION_MODE_OFF;
  OPTIX_CHECK(optixDeviceContextCreate(nullptr, &opts, &context_));
  int dev = 0;
  CUDA_CHECK(cudaGetDevice(&dev));
  cudaDeviceProp prop{};
  CUDA_CHECK(cudaGetDeviceProperties(&prop, dev));
  deviceName_ = prop.name;
  createPipeline();
}

OptixEngine::~OptixEngine() {
  if (pipeline_) optixPipelineDestroy(pipeline_);
  if (hitgroup_) optixProgramGroupDestroy(hitgroup_);
  if (miss_) optixProgramGroupDestroy(miss_);
  if (raygen_) optixProgramGroupDestroy(raygen_);
  if (module_) optixModuleDestroy(module_);
  if (context_) optixDeviceContextDestroy(context_);
}

void OptixEngine::createPipeline() {
  char log[4096];
  size_t logSize = sizeof(log);

  OptixModuleCompileOptions mco{};
  mco.maxRegisterCount = OPTIX_COMPILE_DEFAULT_MAX_REGISTER_COUNT;
  mco.optLevel = OPTIX_COMPILE_OPTIMIZATION_DEFAULT;
  mco.debugLevel = OPTIX_COMPILE_DEBUG_LEVEL_NONE;

  OptixPipelineCompileOptions pco{};
  pco.usesMotionBlur = 0;
  pco.traversableGraphFlags = OPTIX_TRAVERSABLE_GRAPH_FLAG_ALLOW_SINGLE_GAS;
  pco.numPayloadValues = 2;
  pco.numAttributeValues = 0;
  pco.exceptionFlags = OPTIX_EXCEPTION_FLAG_NONE;
  pco.pipelineLaunchParamsVariableName = "params";
  pco.pipelineLaunchParamsSizeInBytes = sizeof(LaunchParams);
  pco.usesPrimitiveTypeFlags = OPTIX_PRIMITIVE_TYPE_FLAGS_CUSTOM;

  OptixResult res = optixModuleCreate(context_, &mco, &pco, reinterpret_cast<const char*>(g_devicePrograms),
                                      g_deviceProgramsSize, log, &logSize, &module_);
  if (res != OPTIX_SUCCESS) throw std::runtime_error(std::string("optixModuleCreate failed: ") + log);

  OptixProgramGroupDesc desc[3] = {};
  desc[0].kind = OPTIX_PROGRAM_GROUP_KIND_RAYGEN;
  desc[0].raygen.module = module_;
  desc[0].raygen.entryFunctionName = "__raygen__frnn";
  desc[1].kind = OPTIX_PROGRAM_GROUP_KIND_MISS;
  desc[1].miss.module = module_;
  desc[1].miss.entryFunctionName = "__miss__frnn";
  desc[2].kind = OPTIX_PROGRAM_GROUP_KIND_HITGROUP;
  desc[2].hitgroup.moduleIS = module_;
  desc[2].hitgroup.entryFunctionNameIS = "__intersection__frnn";
  OptixProgramGroupOptions pgo{};
  OptixProgramGroup groups[3] = {};
  logSize = sizeof(log);
  res = optixProgramGroupCreate(context_, desc, 3, &pgo, log, &logSize, groups);
  if (res != OPTIX_SUCCESS) throw std::runtime_error(std::string("optixProgramGroupCreate failed: ") + log);
  raygen_ = groups[0];
  miss_ = groups[1];
  hitgroup_ = groups[2];

  OptixPipelineLinkOptions plo{};
  plo.maxTraceDepth = 1;
  logSize = sizeof(log);
  res = optixPipelineCreate(context_, &pco, &plo, groups, 3, log, &logSize, &pipeline_);
  if (res != OPTIX_SUCCESS) throw std::runtime_error(std::string("optixPipelineCreate failed: ") + log);

  OptixStackSizes ss{};
  for (OptixProgramGroup g : groups) OPTIX_CHECK(optixUtilAccumulateStackSizes(g, &ss, pipeline_));
  unsigned dcTraversal = 0, dcState = 0, continuation = 0;
  OPTIX_CHECK(optixUtilComputeStackSizes(&ss, 1, 0, 0, &dcTraversal, &dcState, &continuation));
  OPTIX_CHECK(optixPipelineSetStackSize(pipeline_, dcTraversal, dcState, continuation, 1));

  // Header-only SBT records: raygen | miss | hitgroup.
  alignas(OPTIX_SBT_RECORD_ALIGNMENT) char headers[3][OPTIX_SBT_RECORD_HEADER_SIZE];
  for (int i = 0; i < 3; ++i) OPTIX_CHECK(optixSbtRecordPackHeader(groups[i], headers[i]));
  sbtRecords_.alloc(sizeof(headers));
  CUDA_CHECK(cudaMemcpy(sbtRecords_.get(), headers, sizeof(headers), cudaMemcpyHostToDevice));
  const CUdeviceptr base = sbtRecords_.dptr();
  sbt_ = {};
  sbt_.raygenRecord = base;
  sbt_.missRecordBase = base + OPTIX_SBT_RECORD_HEADER_SIZE;
  sbt_.missRecordStrideInBytes = unsigned(OPTIX_SBT_RECORD_HEADER_SIZE);
  sbt_.missRecordCount = 1;
  sbt_.hitgroupRecordBase = base + 2 * OPTIX_SBT_RECORD_HEADER_SIZE;
  sbt_.hitgroupRecordStrideInBytes = unsigned(OPTIX_SBT_RECORD_HEADER_SIZE);
  sbt_.hitgroupRecordCount = 1;
}

size_t OptixEngine::gasOutputBound(uint32_t n) {
  const OptixAccelBuildOptions opts = buildOptions();
  const CUdeviceptr fake = 256;  // not dereferenced by the size query
  const unsigned flags = kGeometryFlags;
  const OptixBuildInput in = customInput(&fake, n, &flags);
  OptixAccelBufferSizes sizes{};
  OPTIX_CHECK(optixAccelComputeMemoryUsage(context_, &opts, &in, 1, &sizes));
  return sizes.outputSizeInBytes;
}

std::pair<OptixTraversableHandle, size_t> OptixEngine::buildUncompacted(const float4* dPoints, uint32_t n,
                                                                       float halfWidth, GasScratch& s,
                                                                       cudaStream_t stream, uint32_t group) {
  group = std::max(1u, group);
  const uint32_t prims = (n + group - 1) / group;
  s.aabbs.ensure(sizeof(AabbF6) * prims);
  launchMakeAabbs(dPoints, s.aabbs.as<AabbF6>(), prims, group, halfWidth, stream);

  const OptixAccelBuildOptions opts = buildOptions();
  const CUdeviceptr aabbPtr = s.aabbs.dptr();
  const unsigned flags = kGeometryFlags;
  const OptixBuildInput in = customInput(&aabbPtr, prims, &flags);
  OptixAccelBufferSizes sizes{};
  OPTIX_CHECK(optixAccelComputeMemoryUsage(context_, &opts, &in, 1, &sizes));
  s.temp.ensure(sizes.tempSizeInBytes);
  s.output.ensure(sizes.outputSizeInBytes);
  s.compactedSize.ensure(sizeof(uint64_t));

  OptixAccelEmitDesc emit{};
  emit.result = s.compactedSize.dptr();
  emit.type = OPTIX_PROPERTY_TYPE_COMPACTED_SIZE;
  OptixTraversableHandle handle = 0;
  OPTIX_CHECK(optixAccelBuild(context_, stream, &opts, &in, 1, s.temp.dptr(), s.temp.bytes(), s.output.dptr(),
                              s.output.bytes(), &handle, &emit, 1));
  uint64_t compacted = 0;
  CUDA_CHECK(cudaMemcpyAsync(&compacted, s.compactedSize.get(), sizeof(compacted), cudaMemcpyDeviceToHost, stream));
  CUDA_CHECK(cudaStreamSynchronize(stream));
  return {handle, size_t(compacted)};
}

GasInfo OptixEngine::buildGas(const float4* dPoints, uint32_t n, float halfWidth, uint64_t dst, size_t dstBytes,
                              GasScratch& s, cudaStream_t stream, uint32_t group) {
  if (n == 0) return {};
  const auto [handle, compacted] = buildUncompacted(dPoints, n, halfWidth, s, stream, group);
  if (compacted > dstBytes) throw std::runtime_error("GAS destination buffer too small");
  GasInfo info;
  OPTIX_CHECK(optixAccelCompact(context_, stream, handle, dst, compacted, &info.handle));
  info.bytes = compacted;
  return info;
}

GasInfo OptixEngine::buildGasOwned(const float4* dPoints, uint32_t n, float halfWidth, DeviceBuffer& out,
                                   GasScratch& s, cudaStream_t stream, uint32_t group) {
  if (n == 0) return {};
  const auto [handle, compacted] = buildUncompacted(dPoints, n, halfWidth, s, stream, group);
  // Free what the compaction does not need before allocating its destination,
  // which lowers the in-core peak from aabbs+temp+output+compact to output+compact.
  s.aabbs.release();
  s.temp.release();
  out.alloc(compacted);
  GasInfo info;
  OPTIX_CHECK(optixAccelCompact(context_, stream, handle, out.dptr(), compacted, &info.handle));
  info.bytes = compacted;
  CUDA_CHECK(cudaStreamSynchronize(stream));
  s.output.release();
  return info;
}

OptixRelocationInfo OptixEngine::relocationInfo(OptixTraversableHandle handle) {
  OptixRelocationInfo info{};
  OPTIX_CHECK(optixAccelGetRelocationInfo(context_, handle, &info));
  int compatible = 0;
  OPTIX_CHECK(optixCheckRelocationCompatibility(context_, &info, &compatible));
  if (!compatible) throw std::runtime_error("acceleration structure is not relocatable on this device");
  return info;
}

OptixTraversableHandle OptixEngine::relocate(const OptixRelocationInfo& info, uint64_t dst, size_t bytes,
                                             cudaStream_t stream) {
  OptixTraversableHandle h = 0;
  OPTIX_CHECK(optixAccelRelocate(context_, stream, &info, nullptr, 0, dst, bytes, &h));
  return h;
}

void OptixEngine::launch(uint64_t dParams, uint32_t width, cudaStream_t stream) {
  if (width == 0) return;
  OPTIX_CHECK(optixLaunch(pipeline_, stream, dParams, sizeof(LaunchParams), &sbt_, width, 1, 1));
}

}  // namespace ooc
